  let argumentCount = call.len - 1
  ex.begin(ctx, factSymbols, callNames)
  var entry = -1
  if entry < 0 and head.symbolValue == sym11 and argumentCount == 0:
    entry = 9
  if entry < 0 and head.symbolValue == sym12 and argumentCount == 0:
    entry = 10
  if entry < 0 and head.symbolValue == sym13 and argumentCount == 1:
    entry = 11
  if entry < 0 and head.symbolValue == sym14 and argumentCount == 1:
    entry = 12
  if entry < 0 and head.symbolValue == sym15 and argumentCount == 0:
    entry = 16
  if entry < 0 and head.symbolValue == sym16 and argumentCount == 0:
    entry = 17
  if entry < 0: return (empty, dsInvalidCall)
  var runResult = 0
  case entry
  of 9:
    runResult = ex.run(method9)
  of 10:
    runResult = ex.run(method10)
  of 11:
    block:
      let argument = call.at(1)[0]
      if not argument.isBound: return (empty, dsInvalidCall)
      ex.v[1] = argument
    runResult = ex.run(method11)
  of 12:
    block:
      let argument = call.at(1)[0]
      if not argument.isBound: return (empty, dsInvalidCall)
      ex.v[1] = argument
    runResult = ex.run(method12)
  of 16:
    runResult = ex.run(method16)
  of 17:
